import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testThreeNumbers() {
        Assert.assertEquals(60, sumArray(intArrayOf(10, 20, 30)))
    }

    @Test
    fun testSingleElement() {
        Assert.assertEquals(5, sumArray(intArrayOf(5)))
    }

    @Test
    fun testEmptyArray() {
        Assert.assertEquals(0, sumArray(intArrayOf()))
    }
}
